type PlanogramWorkspaceProps = {items:PlanItem[];room:{width:number;length:number};selectedId:string|null;onSelect:(id:string|null)=>void;onChange:(items:PlanItem[])=>void;onRoomChange:(room:{width:number;length:number})=>void;floorReference:PlanSurfaceReference|null;wallReference:PlanSurfaceReference|null;onFloorReferenceChange:(reference:PlanSurfaceReference|null)=>void;onWallReferenceChange:(reference:PlanSurfaceReference|null)=>void;onCreateReference:(planImage:string,prompt:string,surfaceReferences:string[])=>void;isCreatingReference:boolean};

function PlanogramWorkspace(props:PlanogramWorkspaceProps){
  const hostRef=useRef<HTMLDivElement>(null);
  const [board,setBoard]=useState<HTMLElement|null>(null);
  const [panel,setPanel]=useState<HTMLElement|null>(null);
  const [camera,setCameraState]=useState<PlanCamera|null>(null);
  const [draggingCamera,setDraggingCamera]=useState(false);
  const cameraRef=useRef<PlanCamera|null>(null);
  const setCamera=(next:PlanCamera|null)=>{cameraRef.current=next;setCameraState(next);if(typeof window!=="undefined"){if(next)sessionStorage.setItem("room-plan-camera",JSON.stringify(next));else sessionStorage.removeItem("room-plan-camera");}};
  useEffect(()=>{const stored=sessionStorage.getItem("room-plan-camera");if(stored){try{const parsed=JSON.parse(stored) as PlanCamera;if(Number.isFinite(parsed.x)&&Number.isFinite(parsed.y)&&Number.isFinite(parsed.height))setCamera(parsed);}catch{sessionStorage.removeItem("room-plan-camera");}}const timer=window.setTimeout(()=>{setBoard(hostRef.current?.querySelector<HTMLElement>(".planogram-editor-board")||null);setPanel(document.querySelector<HTMLElement>(".planogram-panel"));},0);return()=>window.clearTimeout(timer);},[]);
  const placeCamera=(clientX:number,clientY:number)=>{if(!board)return;const rect=board.getBoundingClientRect();const x=Math.max(1,Math.min(99,(clientX-rect.left)/rect.width*100));const y=Math.max(1,Math.min(99,(clientY-rect.top)/rect.height*100));const rotation=Math.atan2(50-y,50-x)*180/Math.PI;setCamera({x,y,height:cameraRef.current?.height||1500,rotation});};
  const cameraBrief=()=>{const current=cameraRef.current;if(!current)return "";const xMm=Math.round(props.room.width*current.x/100);const yMm=Math.round(props.room.length*current.y/100);return `\nКАМЕРА ОБЯЗАТЕЛЬНА: установи виртуальную камеру в точке ${xMm} мм от левого края и ${yMm} мм от верхнего края плана, на высоте ${current.height} мм от пола. Направь объектив из этой точки к центру комнаты (азимут ${Math.round(current.rotation)}°). Сформируй кадр именно от первого лица этой камеры; не показывай камеру на визуализации и не выбирай другой ракурс.`;};
  const enhancedCreate=(planImage:string,prompt:string,surfaceReferences:string[])=>{const current=cameraRef.current;if(!current){props.onCreateReference(planImage,prompt,surfaceReferences);return;}const image=new Image();image.onload=()=>{const canvas=document.createElement("canvas");canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const context=canvas.getContext("2d");if(!context){props.onCreateReference(planImage,prompt+cameraBrief(),surfaceReferences);return;}context.drawImage(image,0,0);const x=canvas.width*current.x/100,y=canvas.height*current.y/100,angle=current.rotation*Math.PI/180;context.save();context.translate(x,y);context.rotate(angle);context.fillStyle="rgba(194,104,29,.24)";context.beginPath();context.moveTo(18,0);context.lineTo(160,-72);context.lineTo(160,72);context.closePath();context.fill();context.fillStyle="#c2681d";context.strokeStyle="#ffffff";context.lineWidth=7;context.fillRect(-28,-20,56,40);context.strokeRect(-28,-20,56,40);context.fillStyle="#ffffff";context.beginPath();context.arc(0,0,9,0,Math.PI*2);context.fill();context.restore();props.onCreateReference(canvas.toDataURL("image/png"),prompt+cameraBrief(),surfaceReferences);};image.onerror=()=>props.onCreateReference(planImage,prompt+cameraBrief(),surfaceReferences);image.src=planImage;};
  return <div ref={hostRef} className="planogram-camera-host" onDoubleClickCapture={(event)=>{const target=event.target as HTMLElement;if(target.closest(".planogram-furniture,.room-resize-handle,.plan-camera-marker"))return;const boardTarget=target.closest(".planogram-editor-board");if(boardTarget)placeCamera(event.clientX,event.clientY);}}><PlanogramWorkspaceBase {...props} onCreateReference={enhancedCreate}/>{board&&camera&&createPortal(<button type="button" className="plan-camera-marker" aria-label="Камера на плане. Перетащите, чтобы изменить ракурс." title="Камера — перетащите в нужную точку" style={{left:`${camera.x}%`,top:`${camera.y}%`,transform:`translate(-50%,-50%) rotate(${camera.rotation}deg)`}} onPointerDown={(event)=>{event.preventDefault();event.stopPropagation();event.currentTarget.setPointerCapture(event.pointerId);setDraggingCamera(true);}} onPointerMove={(event)=>{if(!draggingCamera)return;event.preventDefault();event.stopPropagation();placeCamera(event.clientX,event.clientY);}} onPointerUp={(event)=>{event.stopPropagation();setDraggingCamera(false);}} onPointerCancel={()=>setDraggingCamera(false)}><span/><i/></button>,board)}{panel&&createPortal(<div className="plan-camera-settings"><label>КАМЕРА</label>{camera?<><div className="plan-camera-summary"><i/><span><b>Ракурс установлен</b><small>{Math.round(props.room.width*camera.x/100)} × {Math.round(props.room.length*camera.y/100)} мм на плане</small></span></div><label className="plan-camera-height">ВЫСОТА ОТ ПОЛА, ММ<input type="number" min="300" max="3000" step="50" value={camera.height} onChange={(event)=>{const height=Math.max(300,Math.min(3000,Math.round(Number(event.target.value)||1500)));setCamera({...camera,height});}}/></label><small>Перетащите камеру по плану. Она автоматически направлена к центру комнаты.</small><button type="button" className="plan-camera-remove" onClick={()=>setCamera(null)}>Убрать камеру</button></>:<p>Дважды кликните по свободному месту планограммы, чтобы установить камеру.</p>}</div>,panel)}</div>;
}

function PlanogramWorkspaceBase({items,room,selectedId,onSelect,onChange,onRoomChange,floorReference,wallReference,onFloorReferenceChange,onWallReferenceChange,onCreateReference,isCreatingReference}:PlanogramWorkspaceProps){
  const [dragging,setDragging]=useState<string|null>(null); const [resizing,setResizing]=useState<{id:string;handle:"n"|"ne"|"e"|"se"|"s"|"sw"|"w"|"nw";x:number;y:number;item:PlanItem}|null>(null); const [rotating,setRotating]=useState<{id:string;centerX:number;centerY:number;startAngle:number;startRotation:number}|null>(null); const [editingId,setEditingId]=useState<string|null>(null); const [zoom,setZoom]=useState(100); const [menu,setMenu]=useState<string|null>(null); const [roomResize,setRoomResize]=useState<{mode:"width"|"length";x:number;y:number;width:number;length:number}|null>(null); const fileRef=useRef<HTMLInputElement>(null); const floorRef=useRef<HTMLInputElement>(null); const wallRef=useRef<HTMLInputElement>(null);
  useEffect(()=>{const selectCatalogProduct=(event:Event)=>{const detail=(event as CustomEvent<{index:number;product:CatalogProduct}>).detail;const item=items[detail?.index];const product=detail?.product;if(!item||!product)return;onChange(items.map((current)=>current.id===item.id?{...current,name:product.name,width:product.widthMm||current.width,depth:product.depthMm||current.depth,referenceImage:product.image,referenceImages:product.images,referenceName:product.name,referenceProductId:product.id,referenceArticle:product.article,referenceUrl:product.url,referencePrice:product.price,referenceOldPrice:product.oldPrice,referenceCategory:product.category,referenceSubtype:product.subtype,referenceColor:product.color,referenceMaterial:product.material,referenceHeightMm:product.heightMm,referenceDescription:product.description,referenceParameters:product.parameters}:current));onSelect(item.id);};window.addEventListener("room-plan-catalog-select",selectCatalogProduct);return()=>window.removeEventListener("room-plan-catalog-select",selectCatalogProduct);},[items,onChange,onSelect]);
  const clamp=(value:number,min:number,max:number)=>Math.max(min,Math.min(max,value));
  const itemWidth=(item:PlanItem)=>Math.max(4,item.width/room.width*100); const itemDepth=(item:PlanItem)=>Math.max(4,item.depth/room.length*100);
  const move=(event:React.PointerEvent<HTMLDivElement>)=>{const rect=event.currentTarget.getBoundingClientRect();const x=(event.clientX-rect.left)/rect.width*100;const y=(event.clientY-rect.top)/rect.height*100;if(rotating){const angle=Math.atan2(event.clientY-rotating.centerY,event.clientX-rotating.centerX)*180/Math.PI;const rotation=Math.round((rotating.startRotation+angle-rotating.startAngle+360)%360);onChange(items.map((current)=>current.id===rotating.id?{...current,rotation}:current));return;}if(roomResize){const delta=roomResize.mode==="width"?(event.clientX-roomResize.x)/(rect.width/roomResize.width):(event.clientY-roomResize.y)/(rect.height/roomResize.length);onRoomChange(roomResize.mode==="width"?{...room,width:Math.round(clamp(roomResize.width+delta,2500,14000))}:{...room,length:Math.round(clamp(roomResize.length+delta,2200,11000))});return;}if(resizing){const start=resizing.item;const dx=(event.clientX-resizing.x)/rect.width*room.width;const dy=(event.clientY-resizing.y)/rect.height*room.length;const left=resizing.handle.includes("w"),right=resizing.handle.includes("e"),top=resizing.handle.includes("n"),bottom=resizing.handle.includes("s");let width=start.width+(right?dx:0)-(left?dx:0),depth=start.depth+(bottom?dy:0)-(top?dy:0),itemX=start.x+(left?dx/room.width*100:0),itemY=start.y+(top?dy/room.length*100:0);if(width<200){if(left)itemX-=((200-width)/room.width*100);width=200;}if(depth<200){if(top)itemY-=((200-depth)/room.length*100);depth=200;}itemX=clamp(itemX,0,100-itemWidth({...start,width}));itemY=clamp(itemY,0,100-itemDepth({...start,depth}));onChange(items.map((current)=>current.id===start.id?{...current,x:itemX,y:itemY,width:Math.round(width),depth:Math.round(depth)}:current));return;}if(dragging){const item=items.find((current)=>current.id===dragging);if(!item)return;onChange(items.map((current)=>current.id===item.id?{...current,x:clamp(x-itemWidth(item)/2,0,100-itemWidth(item)),y:clamp(y-itemDepth(item)/2,0,100-itemDepth(item))}:current));}};
  const stop=()=>{setDragging(null);setResizing(null);setRotating(null);setRoomResize(null);};
  const exportPlan=()=>{const blob=new Blob([JSON.stringify({version:"1.2",unit:"mm",room,items,created_at:new Date().toISOString()},null,2)],{type:"application/json"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`room-design-plan-${Date.now()}.json`;link.click();URL.revokeObjectURL(link.href);};
  const downloadPdf=()=>{const printable=`<!doctype html><html><head><meta charset="utf-8"><title>Планограмма ROOM design</title><style>body{font-family:Arial,sans-serif;padding:36px;color:#2b1d14}h1{margin:0 0 8px}p{color:#6e594a}.room{position:relative;width:760px;max-width:100%;aspect-ratio:${room.width}/${room.length};margin:42px 0;border:3px solid #2b1d14;background:#fffdf9;background-image:linear-gradient(#e8e2d5 1px,transparent 1px),linear-gradient(90deg,#e8e2d5 1px,transparent 1px);background-size:24px 24px}.item{position:absolute;display:grid;place-items:center;border:2px solid #6e594a;background:#efe6d8;font-size:12px;font-weight:700}.table,.rug,.chair,.stool{border-radius:50%}.rug.rug-rectangular{border-radius:4px}.sofa{border-radius:12px}</style></head><body><h1>Планограмма</h1><p>Размер помещения: ${room.width} × ${room.length} мм</p><div class="room">${items.map((item)=>`<div class="item ${item.kind}${item.kind==="rug"&&item.rugShape==="rectangular"?" rug-rectangular":""}" style="left:${item.x}%;top:${item.y}%;width:${itemWidth(item)}%;height:${itemDepth(item)}%;transform:rotate(${item.rotation}deg)">${item.name}<br><small>${item.width} × ${item.depth} мм</small></div>`).join("")}</div><script>print()</script></body></html>`;const win=window.open("","_blank","noopener,noreferrer");if(!win){setMenu(null);return;}win.document.write(printable);win.document.close();};
  const createReference=()=>{const canvas=document.createElement("canvas");canvas.width=1600;canvas.height=Math.round(1600*room.length/room.width);const context=canvas.getContext("2d");if(!context)return;context.fillStyle="#f7f2ea";context.fillRect(0,0,canvas.width,canvas.height);context.strokeStyle="#d9cfc2";context.lineWidth=2;for(let x=0;x<canvas.width;x+=60){context.beginPath();context.moveTo(x,0);context.lineTo(x,canvas.height);context.stroke();}for(let y=0;y<canvas.height;y+=60){context.beginPath();context.moveTo(0,y);context.lineTo(canvas.width,y);context.stroke();}context.strokeStyle="#2b1d14";context.lineWidth=8;context.strokeRect(4,4,canvas.width-8,canvas.height-8);items.forEach((item)=>{const x=canvas.width*item.x/100,y=canvas.height*item.y/100,w=canvas.width*itemWidth(item)/100,h=canvas.height*itemDepth(item)/100;context.save();context.translate(x+w/2,y+h/2);context.rotate(item.rotation*Math.PI/180);context.fillStyle=item.kind==="window"?"#cbe2e5":item.kind==="door"?"#d1ae8e":item.kind==="rug"?"#cbb69d":item.kind==="table"?"#dec8ad":"#e6ddd0";context.strokeStyle=item.kind==="window"?"#5d9198":item.kind==="door"?"#76513b":"#5c3d2e";context.lineWidth=4;if(["table","chair","stool"].includes(item.kind)||(item.kind==="rug"&&item.rugShape!=="rectangular")){context.beginPath();context.ellipse(0,0,w/2,h/2,0,0,Math.PI*2);context.fill();context.stroke();}else{context.fillRect(-w/2,-h/2,w,h);context.strokeRect(-w/2,-h/2,w,h);}context.fillStyle="#2b1d14";context.font="600 26px Arial";context.textAlign="center";context.fillText(item.name,0,8);context.restore();});const structural=items.filter((item)=>item.kind==="window"||item.kind==="door");const furnishing=items.filter((item)=>item.kind!=="window"&&item.kind!=="door");const prompt=`Создай фотореалистичную визуализацию интерьера строго по приложенной планограмме. Помещение ${room.width} × ${room.length} мм. Расставь предметы в соответствии с их положением, габаритами в миллиметрах и поворотом: ${furnishing.map((item)=>`${item.name} ${item.width}×${item.depth} мм${item.kind==="rug"?`, форма ${item.rugShape==="rectangular"?"прямоугольная":"круглая или овальная"}`:""}, позиция ${Math.round(item.x)}%/${Math.round(item.y)}%, поворот ${item.rotation}°${item.referenceName?`, используй приложенный референс «${item.referenceName}»`:""}`).join("; ")||"мебель не задана"}. ${structural.length?`ОБЯЗАТЕЛЬНО используй вручную заданные конструктивные элементы строго в указанных местах: ${structural.map((item)=>`${item.name} ${item.width}×${item.depth} мм, позиция ${Math.round(item.x)}%/${Math.round(item.y)}%, поворот ${item.rotation}°`).join("; ")}. Не перемещай и не заменяй их.`:"Окна и дверь на плане не заданы: выбери их расположение, вид и размеры самостоятельно, как лучше для композиции."} ${floorReference?"Используй приложенный референс пола только как обязательный источник цвета и фактуры пола; не меняй его на другой материал.":"Референс пола не задан: самостоятельно выбери материал, цвет и фактуру пола, которые подходят интерьеру."} ${wallReference?"Используй приложенный референс стен только как обязательный источник цвета и фактуры стен; не меняй его на другую отделку.":"Референс стен не задан: самостоятельно выбери цвет и фактуру стен, которые подходят интерьеру."} Сохрани масштаб, свободные проходы и логику планировки. Если приложены фотографии мебели, воспроизведи именно эти предметы. Без текста, логотипов и водяных знаков.`;onCreateReference(canvas.toDataURL("image/png"),prompt,[floorReference?.image,wallReference?.image].filter((image):image is string=>Boolean(image)));};
  const attachReference=(event:React.ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];const id=menu;if(!file||!id)return;const reader=new FileReader();reader.onload=()=>{onChange(items.map((item)=>item.id===id?{...item,referenceImage:String(reader.result||""),referenceName:file.name}:item));setMenu(null);};reader.readAsDataURL(file);event.target.value="";};
  const attachSurfaceReference=(event:React.ChangeEvent<HTMLInputElement>,kind:"floor"|"wall")=>{const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{const reference={image:String(reader.result||""),name:file.name};if(kind==="floor")onFloorReferenceChange(reference);else onWallReferenceChange(reference);};reader.readAsDataURL(file);event.target.value="";};
  const handles:["n"|"ne"|"e"|"se"|"s"|"sw"|"w"|"nw",string][]=[["n","top"],["ne","top-right"],["e","right"],["se","bottom-right"],["s","bottom"],["sw","bottom-left"],["w","left"],["nw","top-left"]];
  return <section className="planogram-workspace" aria-label="Редактор планограммы"><header className="planogram-toolbar"><div><span>ПЛАНОГРАММА</span><b>Гостиная · вид сверху</b></div><div className="planogram-toolbar-actions"><button onClick={()=>setZoom(Math.max(70,zoom-10))}>−</button><em>{zoom}%</em><button onClick={()=>setZoom(Math.min(130,zoom+10))}>+</button><button className="plan-save" onClick={exportPlan}>Сохранить проект</button></div></header><div className="planogram-editor-scroll"><div className="planogram-editor-board planogram-dimensioned-board" style={{transform:`scale(${zoom/100})`,aspectRatio:`${room.width}/${room.length}`}} onPointerMove={move} onPointerUp={stop} onPointerLeave={stop} onPointerDown={(event)=>{if(!(event.target as HTMLElement).closest(".planogram-furniture,.room-resize-handle")){onSelect(null);setEditingId(null);setMenu(null);setRotating(null);}}}><span className="room-measure room-width">{room.width} мм</span><span className="room-measure room-length">{room.length} мм</span><button className="room-resize-handle room-resize-width" aria-label="Изменить ширину комнаты" onPointerDown={(event)=>{event.stopPropagation();event.currentTarget.setPointerCapture(event.pointerId);setRoomResize({mode:"width",x:event.clientX,y:event.clientY,width:room.width,length:room.length});}}/><button className="room-resize-handle room-resize-length" aria-label="Изменить длину комнаты" onPointerDown={(event)=>{event.stopPropagation();event.currentTarget.setPointerCapture(event.pointerId);setRoomResize({mode:"length",x:event.clientX,y:event.clientY,width:room.width,length:room.length});}}/>{items.map((item)=>{const selected=item.id===selectedId;const editing=item.id===editingId;const width=itemWidth(item),depth=itemDepth(item);const architectural=item.kind==="window"||item.kind==="door";return <div key={item.id} className={`planogram-furniture ${item.kind}${item.kind==="rug"&&item.rugShape==="rectangular"?" rug-rectangular":""}${selected?" selected":""}${editing?" editing":""}`} role="button" tabIndex={0} style={{left:`${item.x}%`,top:`${item.y}%`,width:`${width}%`,height:`${depth}%`,transform:`rotate(${item.rotation}deg)`}} onDoubleClick={(event)=>{event.stopPropagation();onSelect(item.id);setEditingId(item.id);setMenu(null);}} onContextMenu={(event)=>{event.preventDefault();event.stopPropagation();onSelect(item.id);setEditingId(null);setMenu(menu===item.id?null:item.id);}} onPointerDown={(event)=>{if((event.target as HTMLElement).closest(".plan-resize-handle,.plan-inline-rotate,.plan-context-menu"))return;event.stopPropagation();event.currentTarget.setPointerCapture(event.pointerId);onSelect(item.id);setEditingId(null);setMenu(null);setDragging(item.id);}} aria-label={`${item.name}: перемещать. Два клика — размеры.`}><i/><span>{item.name}</span>{editing&&<small className="plan-item-size">{item.width} × {item.depth} мм</small>}{editing&&<button type="button" className="plan-inline-rotate" aria-label="Повернуть предмет" title="Зажмите и вращайте" onPointerDown={(event)=>{event.preventDefault();event.stopPropagation();event.currentTarget.setPointerCapture(event.pointerId);const rect=event.currentTarget.parentElement!.getBoundingClientRect();const centerX=rect.left+rect.width/2,centerY=rect.top+rect.height/2;setDragging(null);setResizing(null);setRotating({id:item.id,centerX,centerY,startAngle:Math.atan2(event.clientY-centerY,event.clientX-centerX)*180/Math.PI,startRotation:item.rotation});}}>↻</button>}{editing&&handles.map(([handle,position])=><button key={handle} className={`plan-resize-handle ${position}`} aria-label={`Изменить размер: ${item.name}`} onPointerDown={(event)=>{event.stopPropagation();event.currentTarget.setPointerCapture(event.pointerId);setResizing({id:item.id,handle,x:event.clientX,y:event.clientY,item});}}/>)}{menu===item.id&&!architectural&&<div className="plan-context-menu"><b>{item.name}</b><button type="button" onClick={(event)=>{event.stopPropagation();fileRef.current?.click();}}>Загрузить референс</button>{item.referenceImage&&<button type="button" className="danger" onClick={(event)=>{event.stopPropagation();onChange(items.map((current)=>current.id===item.id?{...current,referenceImage:"",referenceName:""}:current));setMenu(null);}}>Убрать референс</button>}</div>}</div>})}{!items.length&&<div className="planogram-empty-state"><b>Начните расстановку</b><span>Добавьте мебель из панели справа и перетащите её по плану.</span></div>}</div></div><input ref={fileRef} className="plan-reference-input" type="file" accept="image/png,image/jpeg,image/webp" onChange={attachReference}/><input ref={floorRef} className="plan-reference-input" type="file" accept="image/png,image/jpeg,image/webp" onChange={(event)=>attachSurfaceReference(event,"floor")}/><input ref={wallRef} className="plan-reference-input" type="file" accept="image/png,image/jpeg,image/webp" onChange={(event)=>attachSurfaceReference(event,"wall")}/><footer className="planogram-footer"><span>Перетаскивайте предметы. Два клика открывают восемь маркеров изменения размера.</span><b>{items.length} {items.length===1?"элемент":"элементов"}</b></footer><div className="plan-final-actions"><button className="plan-surface-reference" type="button" onClick={()=>floorRef.current?.click()}>{floorReference?<img src={floorReference.image} alt="Референс пола"/>:<i>↥</i>}<span><small>ПОЛ</small><b>{floorReference?"Заменить референс пола":"Добавить референс пола"}</b></span></button><button className="plan-surface-reference" type="button" onClick={()=>wallRef.current?.click()}>{wallReference?<img src={wallReference.image} alt="Референс стен"/>:<i>↥</i>}<span><small>СТЕНЫ</small><b>{wallReference?"Заменить референс стен":"Добавить референс стен"}</b></span></button><button className="plan-create-reference" type="button" onClick={createReference} disabled={isCreatingReference||!items.length}>{isCreatingReference?"Создаём визуализацию…":"Создать визуализацию"}</button></div></section>;
}

function PlanogramPanel({items,room,selectedId,onSelect,onChange}:{items:PlanItem[];room:{width:number;length:number};selectedId:string|null;onSelect:(id:string|null)=>void;onChange:(items:PlanItem[])=>void}){const selected=items.find((item)=>item.id===selectedId);const add=(template:Pick<PlanItem,"kind"|"name"|"width"|"depth">)=>{const id=crypto.randomUUID();const next={...template,id,x:Math.min(70,17+(items.length*11)%58),y:Math.min(70,18+(items.length*9)%52),rotation:0,...(template.kind==="rug"?{rugShape:"round" as const}:{})};onChange([...items,next]);onSelect(id);};const update=(patch:Partial<PlanItem>)=>selected&&onChange(items.map((item)=>item.id===selected.id?{...item,...patch}:item));const updateDimension=(key:"width"|"depth",value:string)=>{const next=Math.round(Number(value));if(Number.isFinite(next)&&next>0)update({[key]:Math.min(next,20000)});};return <div className="panel-content planogram-panel"><p className="choice-intro">Размеры комнаты показаны в миллиметрах. Потяните границу комнаты, чтобы изменить её; перетаскивайте предметы, а двойным кликом открывайте восемь маркеров размера.</p><div className="plan-room-summary"><span>КОМНАТА</span><b>{room.width} × {room.length} мм</b><small>{(room.width*room.length/1000000).toFixed(1)} м²</small></div><label>ДОБАВИТЬ ПРЕДМЕТ</label><div className="plan-template-grid">{planTemplates.map((item)=><button key={item.kind} type="button" onClick={()=>add(item)}><i className={`plan-icon ${item.kind}`}/><span>{item.name}</span></button>)}</div>{selected?<div className="plan-properties"><label>ВЫБРАННЫЙ ПРЕДМЕТ</label><b>{selected.name}</b>{selected.kind==="rug"&&<div className="plan-rug-shape" role="group" aria-label="Форма ковра"><button type="button" className={(selected.rugShape??"round")==="rectangular"?"active":""} onClick={()=>update({rugShape:"rectangular"})}>Прямоугольный</button><button type="button" className={(selected.rugShape??"round")==="round"?"active":""} onClick={()=>update({rugShape:"round"})}>Круглый</button></div>}<strong>{selected.width} × {selected.depth} мм</strong><div className="plan-fields"><label>ШИРИНА, ММ<input aria-label="Ширина предмета в миллиметрах" type="number" min="1" max="20000" step="1" value={selected.width} onChange={(event)=>updateDimension("width",event.target.value)}/></label><label>ГЛУБИНА, ММ<input aria-label="Глубина предмета в миллиметрах" type="number" min="1" max="20000" step="1" value={selected.depth} onChange={(event)=>updateDimension("depth",event.target.value)}/></label></div><small>Введите точные габариты вручную или дважды кликните по предмету на плане и тяните нужный из восьми маркеров по контуру.</small>{selected.referenceImage&&<div className="plan-reference-card"><img src={selected.referenceImage} alt={`Референс: ${selected.name}`}/><span>{selected.referenceName||"Референс предмета"}</span></div>}<button className="plan-rotate" type="button" onClick={()=>update({rotation:(selected.rotation+90)%360})}>↻ Повернуть на 90°</button><button className="plan-delete" type="button" onClick={()=>{onChange(items.filter((item)=>item.id!==selected.id));onSelect(null)}}>Удалить предмет</button></div>:<p className="plan-select-note">Выберите предмет на плане. Для привязки настоящей мебели нажмите на него правой кнопкой и загрузите референс.</p>}</div>}

function Planogram({objects,selected,onSelect}:{objects:DetectedObject[];selected:DetectedObject|null;onSelect:(item:DetectedObject)=>void}) {
  const kindFor = (name:string) => { const value=name.toLowerCase(); if(value.includes("диван")) return "sofa"; if(value.includes("кресло")) return "chair"; if(value.includes("стол")) return "table"; if(value.includes("ковер")) return "rug"; if(value.includes("пуф")) return "pouf"; if(value.includes("торшер")) return "lamp"; if(value.includes("картина")) return "painting"; if(value.includes("растен") || value.includes("дерев")) return "plant"; return "object"; };
  const clamp=(min:number,value:number,max:number)=>Math.min(max,Math.max(min,value));
  return <section className="planogram" aria-label="Планограмма комнаты">
    <div className="planogram-head"><div><span>ПЛАНОГРАММА</span><b>Вид сверху</b></div><small>{objects.length ? `${objects.length} предметов распознано` : "Появится после распознавания"}</small></div>
    <div className={objects.length ? "planogram-board" : "planogram-board planogram-empty"}>
      <div className="planogram-room"><span className="planogram-window">ОКНА</span><span className="planogram-door">ВХОД</span><span className="planogram-room-name">ГОСТИНАЯ</span>
        {objects.map((item,index)=>{const centerX=item.x+item.width/2; const centerY=item.y+item.height/2; const width=clamp(12,item.width*.42+7,31); const height=clamp(9,item.height*.24+6,22); return <button key={item.id} className={`plan-object ${kindFor(item.name)} ${selected?.id===item.id ? "selected" : ""}`} style={{left:`${clamp(9,centerX,91)}%`,top:`${clamp(12,10+centerY*.72,86)}%`,width:`${width}%`,height:`${height}%`,zIndex:index+2}} onClick={()=>onSelect(item)} aria-label={`Выбрать на планограмме: ${item.name}`}><i/><span>{item.name}</span></button>})}
        {!objects.length && <p>Распознайте предметы — здесь появится схема расстановки.</p>}
      </div>
    </div>
    {objects.length>0 && <div className="layer-stack" aria-label="Слои проекта"><div className="layer-stack-head"><span>СЛОИ</span><small>Рабочая структура визуализации</small></div><button className="layer-row base-layer" type="button"><i>▣</i><span><b>Фон</b><small>Исходное пространство</small></span><em>⌁</em></button>{objects.map((item)=>{const active=selected?.id===item.id;return <button key={`layer-${item.id}`} type="button" className={active?"layer-row active":"layer-row"} onClick={()=>onSelect(item)}><i>{kindFor(item.name)==="sofa"?"▰":kindFor(item.name)==="table"?"○":kindFor(item.name)==="plant"?"✦":"□"}</i><span><b>{item.name}</b><small>Предметный слой</small></span><em>⌁</em></button>})}</div>}
    {objects.length>0 && <p className="planogram-note">Схема создана по ракурсу фотографии. Выберите предмет на плане, чтобы подсветить его на визуализации.</p>}
  </section>
}
